import{scenarios,addRequest,prepareBrief,recordsToCsv}from'./intake.mjs';const $=id=>document.getElementById(id);let records=[],active=null;let noticeTimer;
function notice(t){$('notice').textContent=t;$('notice').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').style.display='none',4000)}
function download(content,name,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
async function copy(id){try{await navigator.clipboard.writeText($(id).value);notice('Texto copiado. No se ha enviado.')}catch{$(id).focus();$(id).select();notice('Selecciona y copia el texto resaltado.')}}
function render(){const list=$('record-list');list.replaceChildren();for(const r of records){const card=document.createElement('article');card.className='request-card'+(r.id===active?.id?' active':'');const h=document.createElement('h3');h.textContent=`#${String(r.id).padStart(3,'0')} · ${r.topic}`;const p=document.createElement('p');p.textContent=r.text;const n=document.createElement('p');n.textContent='Próxima acción: '+r.nextAction;if(r.status==='Faltan datos')n.className='warning';const label=document.createElement('label');label.textContent='Estado de la solicitud';label.htmlFor='state-'+r.id;const s=document.createElement('select');s.id='state-'+r.id;for(const v of ['Faltan datos','Pendiente de revisión','En seguimiento','Resuelta']){const o=document.createElement('option');o.value=o.textContent=v;s.append(o)}s.value=r.status;s.onchange=()=>{r.status=s.value;notice('Estado actualizado en esta demo.')};const b=document.createElement('button');b.className='text-button';b.textContent='Ver borrador →';b.onclick=()=>{if(active)active.draft=$('draft').value;active=r;render()};card.append(h,p,n,label,s,b);list.append(card)}$('draft-panel').hidden=!active;if(active)$('draft').value=active.draft}
$('demo-message').value=scenarios.agency;$('scenario').onchange=()=>{$('demo-message').value=scenarios[$('scenario').value]};$('register').onclick=()=>{try{if(active)active.draft=$('draft').value;const result=addRequest(records,$('demo-message').value);records=result.records;active=result.record;render();$('demo-status').textContent=result.duplicate?'Solicitud ya registrada: no se ha creado un duplicado.':'Solicitud organizada en esta demo. Revisa los campos y el borrador.'}catch(e){$('demo-status').textContent=e.message}};
$('reset').onclick=()=>{records=[];active=null;$('draft-panel').hidden=true;$('draft').value='';$('record-list').replaceChildren();const p=document.createElement('p');p.className='fine';p.textContent='Demo reiniciada. Registra un ejemplo para empezar.';$('record-list').append(p);$('demo-status').textContent='Registros de demostración eliminados.'};$('draft').oninput=()=>{if(active)active.draft=$('draft').value};$('copy-draft').onclick=()=>copy('draft');$('download-demo').onclick=()=>{const clean=records.map(({key,...r})=>r);download(JSON.stringify({demo:true,source:'Fictional browser-only simulation; no external integration',records:clean},null,2),'nexotopo-demo-registros.json','application/json')};
$('brief-form').onsubmit=e=>{e.preventDefault();try{$('prepared').value=prepareBrief(Object.fromEntries(['company','task','tools','volume','budget'].map(k=>[k,$(k).value])));$('brief-result').hidden=false;$('brief-status').textContent='Consulta preparada. No se ha enviado.';$('brief-result').scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){notice(e.message)}};$('copy-brief').onclick=()=>copy('prepared');$('download-brief').onclick=()=>download($('prepared').value,'consulta-automatizacion.txt');

$('download-csv').onclick=()=>download(recordsToCsv(records),'nexotopo-demo-registros.csv','text/csv;charset=utf-8');
